INSERT INTO likeness_library (code,archetype,ages,genres,uses,limits,fee,status) VALUES ('LK-01','资深影视表演艺术家 · 男','青年 / 中年 / 老年三版形象','年代剧、家庭剧、历史正剧','AI 电影、剧集角色；需逐项目报备剧本','不得用于广告代言、政治与低俗内容；不得改变人物公众评价','项目授权费 + 发行收益分成','洽谈中（演示）');
INSERT INTO likeness_library (code,archetype,ages,genres,uses,limits,fee,status) VALUES ('LK-02','资深影视表演艺术家 · 女','青年 / 中年两版形象','都市情感、年代、悬疑','AI 电影、剧集角色','不得用于广告代言、敏感题材；声音克隆需单独授权','项目授权费 + 发行收益分成','洽谈中（演示）');
INSERT INTO likeness_library (code,archetype,ages,genres,uses,limits,fee,status) VALUES ('LK-03','戏曲表演艺术家','舞台扮相 / 生活形象','戏曲改编、传统文化题材','戏曲与传统文化主题作品','须保持行当与扮相规范；需艺术顾问审片','公益价 / 商业价分级','洽谈中（演示）');
INSERT INTO likeness_library (code,archetype,ages,genres,uses,limits,fee,status) VALUES ('LK-04','老一辈喜剧演员','青年 / 中年形象','喜剧、合家欢','喜剧短片、贺岁类作品','不得丑化；台词需授权人审阅','按集或按分钟计费','洽谈中（演示）');
INSERT INTO likeness_library (code,archetype,ages,genres,uses,limits,fee,status) VALUES ('LK-05','武打动作演员','动作形象全身扫描','动作、武侠','动作戏份数字替身','不得用于暴力血腥渲染','按镜头计费','洽谈中（演示）');
INSERT INTO likeness_library (code,archetype,ages,genres,uses,limits,fee,status) VALUES ('LK-06','配音表演艺术家','声音授权（不含肖像）','动画、纪录片、译制','旁白与角色配音','不得用于诈骗、冒充等用途；需生成合成标识','按分钟计费 + 分成','洽谈中（演示）');
